using System.Collections;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
using ThinkingSpace.UI;
using Oculus.Interaction;
using Oculus.Interaction.Surfaces;
using System.Collections.Generic;

namespace ThinkingSpace.Companion
{
    [DisallowMultipleComponent]
    public sealed class OrbyOnboardingController : MonoBehaviour
    {
        private enum Step{None,Welcome,Name,MenuInstruction,WaitMenu,MenuOpened,WaitSession,FirstSession,Complete}
        private OrbyVoiceDirector voice;private BrainstormMenuController menu;private ThinkingSpacePreferencesStore preferences;
        private Canvas nameCanvas,skipCanvas;private TMP_InputField nameInput;private Step step;private bool subscribed;
        private bool editingOnly;private int tutorialGeneration;
        private readonly List<Button> keyboardKeys=new List<Button>();private TMP_Text keyboardPageText;private int keyboardPage;
        private static readonly string[] KeyboardPages={"ABCDEFGHIJKLM","NOPQRSTUVWXYZ","0123456789-'"};
        private IEnumerator Start(){voice=GetComponent<OrbyVoiceDirector>();preferences=ThinkingSpacePreferencesStore.CreateForApplication();yield return null;ResolveMenu();
            if(!ShouldBeginTutorial(preferences.Data)){voice?.PlayPrerecorded("greeting_return");yield break;}BeginTutorial();}
        public static bool ShouldBeginTutorial(ThinkingSpacePreferencesData data)=>data==null||!data.WelcomeCompleted||!data.MenuTutorialCompleted||!data.FirstSessionTutorialCompleted;
        private void ResolveMenu(){if(menu==null)menu=FindFirstObjectByType<BrainstormMenuController>();if(menu!=null){preferences=menu.PreferencesStore;if(menu.SessionStore.ActiveSession!=null)voice?.SetActiveSession(menu.SessionStore.ActiveSession.SessionId);if(!subscribed){menu.PalmMenuOpened+=HandleMenuOpened;menu.SessionActivated+=HandleSessionActivated;subscribed=true;}}}
        private void Update(){if(!subscribed)ResolveMenu();if(nameCanvas!=null&&nameCanvas.gameObject.activeSelf&&Camera.main!=null){nameCanvas.transform.position=Camera.main.transform.TransformPoint(new Vector3(0,-.04f,.62f));nameCanvas.transform.rotation=Quaternion.LookRotation(nameCanvas.transform.position-Camera.main.transform.position,Vector3.up);}}
        public void BeginTutorial(){tutorialGeneration++;StopAllCoroutines();voice?.CancelAllSpeech();editingOnly=false;voice?.SetTutorialRecordingBlock(true);ShowSkipControl(true);step=Step.Welcome;PlayThen("greeting_welcome",ShowNameEntry);}
        public void ReplayTutorial(){preferences.SetOnboardingProgress(false,false,false);BeginTutorial();}
        public void SkipTutorial(){tutorialGeneration++;voice?.CancelAllSpeech();if(nameCanvas!=null)nameCanvas.gameObject.SetActive(false);ShowSkipControl(false);preferences.SetOnboardingProgress(true,true,true);step=Step.Complete;voice?.SetTutorialRecordingBlock(false);}
        public void EditPreferredName(){editingOnly=true;ShowNameEntry();}
        private void ShowNameEntry(){step=Step.Name;if(nameCanvas==null)BuildNamePanel();nameInput.text=preferences.Data.PreferredName??"";keyboardPage=0;RefreshKeyboard();nameCanvas.gameObject.SetActive(true);}
        private void ConfirmName(){if(!preferences.SetPreferredName(nameInput.text)){return;}if(editingOnly){editingOnly=false;nameCanvas.gameObject.SetActive(false);return;}nameCanvas.gameObject.SetActive(false);string name=preferences.Data.PreferredName;if(string.IsNullOrEmpty(name)||preferences.Data.PersonalizedGreetingCompleted){ContinueAfterName();return;}int generation=tutorialGeneration;bool finished=false;string greeting=BuildPersonalizedGreeting(name);System.Action<bool> finish=success=>{if(finished)return;finished=true;if(ShouldMarkPersonalizedGreetingCompleted(success))preferences.SetPersonalizedGreetingCompleted(true);if(generation==tutorialGeneration)ContinueAfterName();};if(voice==null||!voice.SpeakOnboardingGreeting(greeting,finish))finish(false);}
        public static bool ShouldMarkPersonalizedGreetingCompleted(bool playbackSucceeded)=>playbackSucceeded;
        public static string BuildPersonalizedGreeting(string validatedName)=>string.IsNullOrEmpty(validatedName)?string.Empty:validatedName+"! Nice to meet you. I've got a feeling we're going to come up with something brilliant together.";
        private void ContinueAfterName(){nameCanvas.gameObject.SetActive(false);preferences.SetOnboardingProgress(true,false,false);step=Step.MenuInstruction;PlayThen("tutorial_menu",()=>step=Step.WaitMenu);}
        private void HandleMenuOpened(){if(step!=Step.WaitMenu)return;step=Step.MenuOpened;preferences.SetOnboardingProgress(true,true,false);PlayThen("tutorial_menu_opened",()=>step=Step.WaitSession);}
        private void HandleSessionActivated(BrainstormSession session){voice?.SetActiveSession(session.SessionId);if(step!=Step.WaitSession)return;step=Step.FirstSession;PlayThen("tutorial_first_session",()=>{preferences.SetOnboardingProgress(true,true,true);step=Step.Complete;ShowSkipControl(false);voice?.SetTutorialRecordingBlock(false);});}
        private void PlayThen(string key,System.Action next){int generation=tutorialGeneration;if(voice==null||!voice.PlayPrerecorded(key,null,_=>{if(generation==tutorialGeneration)next?.Invoke();}))next?.Invoke();}
        private void BuildNamePanel()
        {
            GameObject root=new GameObject("Preferred Name Entry",typeof(RectTransform),typeof(Canvas),typeof(GraphicRaycaster),typeof(Image));nameCanvas=root.GetComponent<Canvas>();nameCanvas.renderMode=RenderMode.WorldSpace;nameCanvas.overrideSorting=true;nameCanvas.sortingOrder=100;RectTransform rect=root.GetComponent<RectTransform>();rect.sizeDelta=new Vector2(700,620);rect.localScale=Vector3.one*.0005f;root.GetComponent<Image>().color=new Color(.03f,.05f,.09f,.98f);PointableCanvas pointable=root.AddComponent<PointableCanvas>();pointable.InjectAllPointableCanvas(nameCanvas);PlaneSurface plane=root.AddComponent<PlaneSurface>();plane.InjectAllPlaneSurface(PlaneSurface.NormalFacing.Backward,false);BoundsClipper clipper=root.AddComponent<BoundsClipper>();clipper.Size=new Vector3(700,620,.01f);ClippedPlaneSurface clipped=root.AddComponent<ClippedPlaneSurface>();clipped.InjectAllClippedPlaneSurface(plane,new List<IBoundsClipper>{clipper});RayInteractable ray=root.AddComponent<RayInteractable>();ray.InjectAllRayInteractable(clipped);ray.InjectOptionalPointableElement(pointable);PokeInteractable poke=root.AddComponent<PokeInteractable>();poke.InjectAllPokeInteractable(clipped);poke.InjectOptionalPointableElement(pointable);
            MakeText("What should Orby call you?",rect,34,new Vector2(.08f,.88f),new Vector2(.92f,.97f));GameObject input=new GameObject("Name Display",typeof(RectTransform),typeof(Image),typeof(TMP_InputField));input.transform.SetParent(rect,false);RectTransform ir=input.GetComponent<RectTransform>();ir.anchorMin=new Vector2(.08f,.75f);ir.anchorMax=new Vector2(.92f,.85f);ir.offsetMin=ir.offsetMax=Vector2.zero;input.GetComponent<Image>().color=new Color(.12f,.18f,.28f,1);nameInput=input.GetComponent<TMP_InputField>();TMP_Text inputText=MakeText("Text",ir,30,new Vector2(.04f,.05f),new Vector2(.96f,.95f));inputText.alignment=TextAlignmentOptions.Left;nameInput.textComponent=inputText;nameInput.characterLimit=32;nameInput.contentType=TMP_InputField.ContentType.Name;nameInput.readOnly=true;nameInput.shouldHideMobileInput=true;nameInput.shouldHideSoftKeyboard=true;
            for(int i=0;i<14;i++){int index=i;int row=i/7,column=i%7;float x0=.05f+column*.13f,x1=x0+.105f,y1=.69f-row*.13f,y0=y1-.105f;Button key=MakeButton("",rect,new Vector2(x0,y0),new Vector2(x1,y1));key.onClick.AddListener(()=>PressKey(index));keyboardKeys.Add(key);}
            Button previous=MakeButton("Previous",rect,new Vector2(.05f,.33f),new Vector2(.25f,.42f));previous.onClick.AddListener(()=>{keyboardPage=Mathf.Max(0,keyboardPage-1);RefreshKeyboard();});keyboardPageText=MakeText("Page",rect,22,new Vector2(.27f,.33f),new Vector2(.47f,.42f));Button next=MakeButton("Next",rect,new Vector2(.49f,.33f),new Vector2(.69f,.42f));next.onClick.AddListener(()=>{keyboardPage=Mathf.Min(KeyboardPages.Length-1,keyboardPage+1);RefreshKeyboard();});Button back=MakeButton("⌫",rect,new Vector2(.71f,.33f),new Vector2(.82f,.42f));back.onClick.AddListener(Backspace);Button space=MakeButton("Space",rect,new Vector2(.84f,.33f),new Vector2(.95f,.42f));space.onClick.AddListener(()=>AppendCharacter(' '));
            Button confirm=MakeButton("Confirm",rect,new Vector2(.05f,.19f),new Vector2(.45f,.28f));confirm.onClick.AddListener(ConfirmName);Button skipName=MakeButton("Skip Name",rect,new Vector2(.55f,.19f),new Vector2(.95f,.28f));skipName.onClick.AddListener(()=>{preferences.SetPreferredName("");preferences.SetPersonalizedGreetingCompleted(true);if(editingOnly){editingOnly=false;nameCanvas.gameObject.SetActive(false);}else ContinueAfterName();});Button skipTutorial=MakeButton("Skip Tutorial",rect,new Vector2(.3f,.04f),new Vector2(.7f,.13f));skipTutorial.onClick.AddListener(SkipTutorial);RefreshKeyboard();
            ThinkingSpaceLocalizationController.LocalizeKnownText(root);
        }
        private void PressKey(int index){string page=KeyboardPages[keyboardPage];if(index<page.Length)AppendCharacter(page[index]);}
        private void AppendCharacter(char value){if(nameInput==null||nameInput.text.Length>=32)return;nameInput.text+=value;nameInput.caretPosition=nameInput.text.Length;}
        private void Backspace(){if(nameInput==null||nameInput.text.Length==0)return;nameInput.text=nameInput.text.Substring(0,nameInput.text.Length-1);nameInput.caretPosition=nameInput.text.Length;}
        private void RefreshKeyboard(){if(keyboardKeys.Count==0)return;string page=KeyboardPages[Mathf.Clamp(keyboardPage,0,KeyboardPages.Length-1)];for(int i=0;i<keyboardKeys.Count;i++){bool active=i<page.Length;keyboardKeys[i].gameObject.SetActive(active);TMP_Text label=keyboardKeys[i].GetComponentInChildren<TMP_Text>();if(label!=null)label.text=active?page[i].ToString():"";}if(keyboardPageText!=null)keyboardPageText.text=ThinkingSpaceLocalizationController.Get("common.page_format",keyboardPage+1,KeyboardPages.Length);}
        private void ShowSkipControl(bool visible)
        {
            if(!visible){if(skipCanvas!=null)skipCanvas.gameObject.SetActive(false);return;}
            if(skipCanvas==null)
            {
                GameObject root=new GameObject("Tutorial Skip Control",typeof(RectTransform),typeof(Canvas),typeof(GraphicRaycaster),typeof(Image));root.transform.SetParent(transform,false);skipCanvas=root.GetComponent<Canvas>();skipCanvas.renderMode=RenderMode.WorldSpace;skipCanvas.overrideSorting=true;skipCanvas.sortingOrder=101;RectTransform rect=root.GetComponent<RectTransform>();rect.sizeDelta=new Vector2(300,90);rect.localScale=Vector3.one*.0005f;rect.localPosition=new Vector3(0,-.28f,.02f);root.GetComponent<Image>().color=new Color(.03f,.05f,.09f,.92f);PointableCanvas pointable=root.AddComponent<PointableCanvas>();pointable.InjectAllPointableCanvas(skipCanvas);PlaneSurface plane=root.AddComponent<PlaneSurface>();plane.InjectAllPlaneSurface(PlaneSurface.NormalFacing.Backward,false);BoundsClipper clipper=root.AddComponent<BoundsClipper>();clipper.Size=new Vector3(300,90,.01f);ClippedPlaneSurface clipped=root.AddComponent<ClippedPlaneSurface>();clipped.InjectAllClippedPlaneSurface(plane,new List<IBoundsClipper>{clipper});RayInteractable ray=root.AddComponent<RayInteractable>();ray.InjectAllRayInteractable(clipped);ray.InjectOptionalPointableElement(pointable);PokeInteractable poke=root.AddComponent<PokeInteractable>();poke.InjectAllPokeInteractable(clipped);poke.InjectOptionalPointableElement(pointable);Button button=MakeButton("Skip Tutorial",rect,new Vector2(.08f,.15f),new Vector2(.92f,.85f));button.onClick.AddListener(SkipTutorial);
                ThinkingSpaceLocalizationController.LocalizeKnownText(root);
            }
            skipCanvas.gameObject.SetActive(true);
        }
        private static TMP_Text MakeText(string value,Transform parent,float size,Vector2 min,Vector2 max){GameObject go=new GameObject(value,typeof(RectTransform));go.transform.SetParent(parent,false);RectTransform r=go.GetComponent<RectTransform>();r.anchorMin=min;r.anchorMax=max;r.offsetMin=r.offsetMax=Vector2.zero;var text=go.AddComponent<TextMeshProUGUI>();text.font=TMP_Settings.defaultFontAsset;text.fontSize=size;text.text=value;text.alignment=TextAlignmentOptions.Center;text.color=Color.white;return text;}
        private static Button MakeButton(string label,Transform parent,Vector2 min,Vector2 max){GameObject go=new GameObject(label,typeof(RectTransform),typeof(Image),typeof(Button));go.transform.SetParent(parent,false);RectTransform r=go.GetComponent<RectTransform>();r.anchorMin=min;r.anchorMax=max;r.offsetMin=r.offsetMax=Vector2.zero;go.GetComponent<Image>().color=new Color(.08f,.52f,.72f,1);Button b=go.GetComponent<Button>();MakeText(label,r,25,Vector2.zero,Vector2.one);return b;}
        private void OnDestroy(){if(menu!=null&&subscribed){menu.PalmMenuOpened-=HandleMenuOpened;menu.SessionActivated-=HandleSessionActivated;}}
    }
}
